source.reference:
def send_mail(ctx, to, body):
    require_capability(ctx, "mail:send:internal")
    if to.domain not in ALLOWED:
        return deny("egress_allowlist")
    if ctx.risk > LOW and not ctx.approved:
        return deny("approval_required")
    audit(ctx, to, body)
    return smtp.send(to=to, body=body)
